scwin.fn_GetPar;
scwin.cond_nm = "";
scwin.cond_con = "";

// 이전 버튼의 위치를 기억하고 있어야 한다.. 작업을 하지 않고 닫기를  눌렀을경우. 꼬임방지를 위해서~~~
scwin.before_bas_btn = 0;
scwin.before_horiz_btn = 0;
scwin.before_verti_btn = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  이전 라디오 버튼 정보 가져온다
 */
scwin.fn_setBeforeRadioBtn = function() {
    scwin.before_bas_btn = $c.stf.getObjectValue(rdo_Bas);
    scwin.before_horiz_btn = $c.stf.getObjectValue(rdo_Horiz);
    scwin.before_verti_btn = $c.stf.getObjectValue(rdo_Verti);
};


/**
 *  라디오버튼 정보를 등록
 */
scwin.fn_getBeforeRadioBtn = function(rdo_btn) {
    if (rdo_btn == "ALL") {
        rdo_Bas.setValue(scwin.before_bas_btn);
        rdo_Horiz.setValue(scwin.before_horiz_btn);
        rdo_Verti.setValue(scwin.before_verti_btn);
    } else if (rdo_btn == "rdo_Bas") {
        rdo_Bas.setValue(scwin.before_bas_btn);
    } else if (rdo_btn == "rdo_Horiz") {
        rdo_Horiz.setValue(scwin.before_horiz_btn);
    } else if (rdo_btn == "rdo_Verti") {
        rdo_Verti.setValue(scwin.before_verti_btn);
    }
};




/**
 *  조건검색 타이틀 세팅
 */
scwin.fn_setCondTitle = function(condTitle) {
    $c.stf.setObjectValue(txb_conditionTitle, condTitle);
};


/**
