scwin.fn_ClearDs = function() {
    //dts_List.ClearData();

    //dts_KeyInfo.ClearData();

};

/**
 * 조회
 */
scwin.fn_search = function() {
    //데이터셋 초기화
    scwin.fn_ClearDs();

    // 일단 조건을 저장하자. 화면에서 조건을 만들어 넘겼는데 세로항목이 많아지니까 화면에서 뻗어버린다.
    if (!scwin.fn_SaveTemp()) {
        return;
    } else {
        scwin.fn_search2();
    }
};



/**
 * 조회 step2
 */
scwin.fn_search2 = function() {
    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=" + scwin.fn_GetQueryId() + "&outputMessageId=FIS_COND_SRCH_LIST" + scwin.fn_GetCondition();
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 임시저장 
 */
scwin.fn_SaveTemp = function() {
    // 저장용 데이터 세팅
    if (!scwin.fn_SetSaveData()) {
        return false;
    }

    // 임시저장여부에따라 분기. 조건이 조건읽기 팝업에서 세팅된경우는 임시저장 하지 않는다.
    if (scwin.vTmpSave) {
        trs_save.Action = "/ConditionSrchAction.do?method=saveCondition" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&outputMessageId=FIS_KEY_INFO";
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(O:pOutput=dts_KeyInfo,I:pInput1=dts_Fz530,I:pInput2=dts_Fz531)";
        //trs_save.Parameters	= "EMP_NO=" + js_emp_no +",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
    return true;
};



/**
 * 저장될 데이터를 세팅한다.
 */
scwin.fn_SetSaveData = function() {
    // 저장전 체크.
    if (!scwin.fn_ChkValid()) {
        return false;
    }

    // 저장용 데이터 세팅.
    dts_Fz530.removeAll();
    dts_Fz530.insertRow();
    dts_Fz530.setCellData(1, "EMP_NO", js_emp_no);
    dts_Fz530.setCellData(1, "TYP", "1");
    dts_Fz530.setCellData(1, "GUBUN", "1");
    if (scwin.vTmpSave == true) {
        dts_Fz530.setCellData(1, "COND_NM", ""); //제목 : 저장팝업에서 세팅
        dts_Fz530.setCellData(1, "COND_CON", ""); //상세내용 : 저장팝업에서 세팅

    } else {
        dts_Fz530.setCellData(1, "COND_NM", scwin.cond_nm); //제목 : 본화면에서 세팅
        dts_Fz530.setCellData(1, "COND_CON", scwin.cond_con); //상세내용 : 본화면에서 세팅

    }
    dts_Fz530.setCellData(1, "COND_SUBCON", ""); //사용안함
    dts_Fz530.setCellData(1, "CONTENT", scwin.fn_GetConditionString()); //조회조건

    // 키정보 세팅.
    dts_Fz530.setCellData(1, "SEQ_NO", dts_KeyInfo.getTotalRow() > 0 ? dts_KeyInfo.getCellData(1, "SEQ_NO") : "");

    // 데이터셋이 변경되어야만 서버로 전송된다. 강제로 변경
    for (var nRow = 1; nRow <= dts_Fz531.getTotalRow(); nRow++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Fz531.UserStatus(nRow) = 1; // row의 상태를 강제로 변경.*/
        X = 1; // row의 상태를 강제로 변경.

    }
    return true;
};


/**
 * 조회조건 get방식의 문자열 만들기
 */
scwin.fn_GetCondition = function() {
    var sCondition = "";
    sCondition = "&{P}IND_PTTN=" + $c.stf.getObjectValue(cmb_IND_PTTN) + "&{P}FISCAL_TYP=" + $c.stf.getObjectValue(cmb_FISCAL_TYP) + "&{P}INDVDL_CONN_TP=" + $c.stf.getObjectValue(cmb_INDVDL_CONN_TP) + "&{P}ACNTG_BAS_TYP=" + $c.stf.getObjectValue(cmb_ACNTG_BAS_TYP); // G KGGAP, I IFRS

    // 기준, 가로, 세로 조건에 담기.
    var sVerti = "";
    var sBase = "";
    var nCntHoriz = 0;
    for (var nRow = 1; nRow <= dts_Fz531.getTotalRow(); nRow++) {
        var AXIS_TYP = dts_Fz531.getCellData(nRow, "AXIS_TYP"); // 1 기준, 2 가로, 3 세로
        var ITEM_CD = dts_Fz531.getCellData(nRow, "ITEM_CD");

        // 기준
        if (AXIS_TYP == "1") {
            sCondition += "&{P}BASE=" + ITEM_CD;
        }
        // 가로
        else if (AXIS_TYP == "2") {
            var COL_YEAR = dts_Fz531.getCellData(nRow, "COL_YEAR");
            var FIELD_IDX = dts_Fz531.getCellData(nRow, "FIELD_IDX");
            if (COL_YEAR != "0000") {
                sCondition += "&{P}HORIZ_YYYY" + FIELD_IDX + "=" + COL_YEAR;
                if (sBase.indexOf(COL_YEAR) == -1) {
                    sBase += ",'" + COL_YEAR + "'";
                }
            }
            sCondition += "&{P}HORIZ_" + FIELD_IDX + "=" + ITEM_CD;
            nCntHoriz = Number(FIELD_IDX);
        }
        // 세로
        else if (AXIS_TYP == "3") {
            var COL_YEAR = dts_Fz531.getCellData(nRow, "COL_YEAR");
            var FIELD_IDX = dts_Fz531.getCellData(nRow, "FIELD_IDX");
            if (COL_YEAR != "0000") {
                if (sBase.indexOf(COL_YEAR) == -1) {
                    sBase += ",'" + COL_YEAR + "'";
                }
            }
        }
    }
    //sCondition += "&{P}VERTI=" + sVerti.substring(1);
    sCondition += "&{P}BASE_LIST=" + sBase.substring(1);
    sCondition += "&{P}TABLE_NM=" + scwin.fn_GetTableName();
    sCondition += "&{P}EMP_NO=" + dts_KeyInfo.getCellData(1, "EMP_NO");
    sCondition += "&{P}TYP=" + dts_KeyInfo.getCellData(1, "TYP");
    sCondition += "&{P}GUBUN=" + dts_KeyInfo.getCellData(1, "GUBUN");
    sCondition += "&{P}SEQ_NO=" + dts_KeyInfo.getCellData(1, "SEQ_NO");

    // 파라미터가 없으면 에러나기때문에 강제로 만들자.
    for (nCntHoriz++; nCntHoriz < scwin.vHorizLimitCnt; nCntHoriz++) {
        sCondition += "&{P}HORIZ_" + nCntHoriz + "=";
        sCondition += "&{P}HORIZ_YYYY" + nCntHoriz + "=";
    }
    return sCondition;
};


/**
 * 조건에따라 테이블이름 구하기.
 * TB_FN_FE110	개별 KGGAP
 * TB_FN_FE120	개별 IFRS
 * TB_FN_FE310	연결 KGGAP
 * TB_FN_FE320	연결 IFRS
 */
scwin.fn_GetTableName = function() {
    var sTableNm = "";
    var sIndvdlConnTp = $c.stf.getObjectValue(cmb_INDVDL_CONN_TP); // 1 개별, 2 연결
    var sAcntgBasTyp = $c.stf.getObjectValue(cmb_ACNTG_BAS_TYP); // G KGGAP, I IFRS

    if (sIndvdlConnTp == "1" && sAcntgBasTyp == "G") {
        sTableNm = "TB_FN_FE110";
    } else if (sIndvdlConnTp == "1" && sAcntgBasTyp == "I") {
        sTableNm = "TB_FN_FE120";
    } else if (sIndvdlConnTp == "2" && sAcntgBasTyp == "G") {
        sTableNm = "TB_FN_FE310";
    } else if (sIndvdlConnTp == "2" && sAcntgBasTyp == "I") {
        sTableNm = "TB_FN_FE320";
    }
    return sTableNm;
};


/**
 * 조회유형에따른 queryId 구하기.
 * 유형 A1 [기준 : 년도, 가로 : 기업, 세로 : 재무계정]  1/2/3  krx.lds.stf.fis.select.condSrchA1
 * 유형 A2 [기준 : 년도, 가로 : 재무계정, 세로 : 기업]  1/3/2
 * 유형 B1 [기준 : 기업, 가로 :  년도, 세로 :재무계정]  2/1/3
 * 유형 B2 [기준 : 기업, 가로 :  재무계정, 세로 :년도]  2/3/1
 * 유형 C1 [기준 : 재무계정, 가로 :  년도, 세로 :기업]  3/1/2
 * 유형 C2 [기준 : 재무계정, 가로 :  기업, 세로 :년도]  3/2/1
 * 유형 D1 [기준 : 없음, 가로 :  재무계정(데이터조회기준년도 체크), 세로 :기업]  없음/3/2
 * 유형 D2 [기준 : 없음, 가로 :  기업(데이터조회기준년도 체크), 세로 :재무계정]  없음/2/3
 * 유형 D3 [기준 : 없음, 가로 :  재무계정, 세로 :기업(데이터조회기준년도 체크)]  없음/3/2
 * 유형 D4 [기준 : 없음, 가로 :  기업, 세로 :재무계정(데이터조회기준년도 체크)]  없음/2/3
 */
scwin.fn_GetQueryId = function() {
    var vQueryId = "";

    // AXIS_TYP  1 기준, 2 가로축, 3 세로축  
    var nTmpIdx1 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "1");
    var nTmpIdx2 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    var nTmpIdx3 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "3");

    // 기준이 존재하면 (A, B, C) 유형임.
    if (nTmpIdx1 >= 1) {
        var ITEM_TYP1 = dts_Fz531.getCellData(nTmpIdx1, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
        var ITEM_TYP2 = dts_Fz531.getCellData(nTmpIdx2, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사

        // A타입
        if (ITEM_TYP1 == "0") {
            if (ITEM_TYP2 == "3") {
                vQueryId = "krx.lds.stf.fis.select.condSrchA1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchA2";
            }
            // C 타입

        } else if (ITEM_TYP1 == "1") {
            if (ITEM_TYP2 == "0") {
                vQueryId = "krx.lds.stf.fis.select.condSrchC1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchC2";
            }
            // B 타입

        } else if (ITEM_TYP1 == "3") {
            if (ITEM_TYP2 == "0") {
                vQueryId = "krx.lds.stf.fis.select.condSrchB1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchB2";
            }
        }
        // D 타입(년도가 가로에 붙었냐? 세로에 붙었냐??)

    } else {
        // 년도가 가로에 붙었는지 세로에 붙었는지 확인.
        // 가로에 붙었다.
        if (dts_Fz531.getCellData(nTmpIdx2, "COL_YEAR") != "0000") {
            var ITEM_TYP = dts_Fz531.getCellData(nTmpIdx2, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
            if (ITEM_TYP == "1") {
                vQueryId = "krx.lds.stf.fis.select.condSrchD1";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchD2";
            }
        }
        // 세로에 붙었다.
        else if (dts_Fz531.getCellData(nTmpIdx3, "COL_YEAR") != "0000") {
            var ITEM_TYP = dts_Fz531.getCellData(nTmpIdx3, "ITEM_TYP"); // ITEM_TYP  0 년도, 1 계정, 3 회사
            if (ITEM_TYP == "3") {
                vQueryId = "krx.lds.stf.fis.select.condSrchD3";
            } else {
                vQueryId = "krx.lds.stf.fis.select.condSrchD4";
            }
        } else {
            $c.win.alert("쿼리ID를 찾을 수 없습니다.");
            return "";
        }
    }
    return vQueryId;
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function() {
    // 가로, 세로 항목은 필수. AXIS_TYP 1/기준, 2/가로축, 3/세로축
    var nTmpIdx1 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "1");
    var nTmpIdx2 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    var nTmpIdx3 = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "3");
    var COL_YEAR1 = dts_Fz531.getCellData(nTmpIdx2, "COL_YEAR");
    var COL_YEAR2 = dts_Fz531.getCellData(nTmpIdx3, "COL_YEAR");
    if (nTmpIdx2 < 1) {
        $c.win.alert("가로항목을 선택하세요.");
        return false;
    }
    if (nTmpIdx3 < 1) {
        $c.win.alert("세로항목을 선택하세요.");
        return false;
    }
    // 기준이 없다면 가로항목의 데이터조회기준년도가 체크되어 있으면 됨. 즉  COL_YEAR 값이 0000이 아님.
    if (nTmpIdx1 < 1) {
        if (COL_YEAR1 == "0000" && COL_YEAR2 == "0000") {
            $c.win.alert("기준을 지정하세요.");
            return false;
        }
    }
    return true;
};


/**
 * 기준지정 팝업 오픈
 */
scwin.fn_OpenBasePop = async function() {
    // 가로 세팅중  1 기준, 2 가로, 3 세로
    scwin.vAxisType = "1";

    // 1 : 년도, 2 : 기업, 3 : 재무계정
    var sBas = $c.stf.getObjectValue(rdo_Bas);
    var sHoriz = $c.stf.getObjectValue(rdo_Horiz);
    var sVerti = $c.stf.getObjectValue(rdo_Verti);

    // 기준, 세로와 동일한것이 선택되었다면..
    if (sBas == sHoriz || sBas == sVerti) {
        $c.win.alert("이미 선택되었습니다.");
        scwin.fn_getBeforeRadioBtn("rdo_Bas");
        return;
    }
    var arrPos = $c.stf.getLeftTopPos(rdo_Bas);
    if (sBas == "1") {
        await $c.frame.CreateDialogFrame("YYYY", "./ULDFIS00600_P1.gfm", "연도검색", arrPos[0].LEFT, arrPos[0].TOP, 360 + 20, 460 + 40, "window");
    } else if (sBas == "2") {
