/**
 * 각 축정보 세팅
 */
scwin.fn_SetAxisInfo = function(pArr) {
    scwin.fn_setBeforeRadioBtn();
    scwin.fn_SetDtsFz531(pArr);
};


/**
 * 기준, 가로, 세로 항목 정보를  DtsFz531 에 세팅.
 *  pAxisTyp : 1/기준, 2/가로축, 3/세로축
 */
scwin.fn_SetDtsFz531 = function(pArr) {
    // 임시저장여부 세팅
    scwin.vTmpSave = true;

    // 세팅전 각 축 정보를 삭제. 
    scwin.fn_InitAxisInfo(pArr[0].AXIS_TYP);

    // 가로인 경우
    if (pArr[0].AXIS_TYP == "2") {
        if (pArr.length < 10) {
            $c.cm.setColumnProp(grd_List, "NAME", "width", 118 + (111 * 1));
        } else {
            $c.cm.setColumnProp(grd_List, "NAME", "width", 118);
        }
    }

    // 데이터조회기준년도 체크 시 기준지정은 비활성.
    if ((pArr[0].AXIS_TYP == "2" || pArr[0].AXIS_TYP == "3") && pArr[0].COL_YEAR != "0000") {
        rdo_Bas.setValue("");
        rdo_Bas.setDisabled(true);
        rdo_Bas.Reset();
        $c.win.alert("데이터조회기준년도 체크 시 기준지정은 비활성됩니다");
    } else {
        rdo_Bas.setDisabled(false);
        rdo_Bas.Reset();
    }
    for (var nIdx = 0; nIdx < pArr.length; nIdx++) {
        dts_Fz531.insertRow();
        var nRow = dts_Fz531.getRowPosition();
        dts_Fz531.setCellData(nRow, "EMP_NO", js_emp_no);
        dts_Fz531.setCellData(nRow, "COND_TYP", "1");
        dts_Fz531.setCellData(nRow, "COND_GUBUN", "1");
        dts_Fz531.setCellData(nRow, "AXIS_TYP", pArr[nIdx].AXIS_TYP);
        dts_Fz531.setCellData(nRow, "ITEM_CD", pArr[nIdx].ITEM_CD);
        dts_Fz531.setCellData(nRow, "ITEM_TYP", pArr[nIdx].ITEM_TYP);
        dts_Fz531.setCellData(nRow, "ITEM_NM", pArr[nIdx].ITEM_NM);
        dts_Fz531.setCellData(nRow, "COL_YEAR", pArr[nIdx].COL_YEAR);
        dts_Fz531.setCellData(nRow, "ACCNT_EXP_TYP", "0"); // 0 일반
        dts_Fz531.setCellData(nRow, "FIELD_IDX", nIdx);
        dts_Fz531.setCellData(nRow, "USE_YN", "Y");
        dts_Fz531.setCellData(nRow, "SAVE_YN", "Y");
    }

    // 그리드 타이틀 세팅. 매번 새로 세팅함.
    //fn_SetGrdTitle(vAxisType);
    scwin.fn_SetGrdTitle("9");
};


/**
 * 그리드 타이틀 세팅.
 * AXIS_TYP : 1/기준, 2/가로, 3/세로
 */
scwin.fn_SetGrdTitle = function(pGubun) {
    if (pGubun == "1") {
        scwin.fn_SetGrdTitleBase();
    } else if (pGubun == "2") {
        scwin.fn_SetGrdTitleHoriz();
    } else if (pGubun == "3") {
        scwin.fn_SetGrdTitleVerti();
    } else {
        scwin.fn_SetGrdTitleBase();
        scwin.fn_SetGrdTitleHoriz();
        scwin.fn_SetGrdTitleVerti();
    }
};



/**
 * 그리드 타이틀 세팅_기준
 * AXIS_TYP : 1/기준, 2/가로, 3/세로
 */
scwin.fn_SetGrdTitleBase = function() {
    //txb_Year.value = pVal;
    //txb_Com.value = pVal;
    //txb_Accnt.value = pVal;
    //fn_InitGrid(1);
    var nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "1");
    if (nRow >= 1) {
        $c.cm.setColumnProp(grd_List, "NAME", "Name", "기준:" + $c.stf.trim(dts_Fz531.getCellData(nRow, "ITEM_NM")));
    } else {
        $c.cm.setColumnProp(grd_List, "NAME", "Name", "");
    }
};



/**
 * 그리드 타이틀 세팅_가로
 * AXIS_TYP : 1/기준, 2/가로, 3/세로
 */
scwin.fn_SetGrdTitleHoriz = function() {
    // 그리드 초기화
    scwin.fn_InitGrid("2");
    var nIdx = 1;
    var nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    for (; nRow <= dts_Fz531.getTotalRow(); nRow++) {
        // 가로 세팅  1/기준, 2/가로, 3/세로
        if (dts_Fz531.getCellData(nRow, "AXIS_TYP") != "2") {
            break;
        }
        $c.cm.setColumnProp(grd_List, "ACCNT_VAL" + nIdx, "Name", $c.stf.trim(dts_Fz531.getCellData(nRow, "ITEM_NM")));
        $c.cm.setColumnProp(grd_List, "ACCNT_VAL" + nIdx, "Show", true);
        nIdx++;
    }

    // 넓이 세팅
    if (nIdx < 11) {
        $c.cm.setColumnProp(grd_List, "NAME", "width", 118 + (111 * 1));
    } else {
        $c.cm.setColumnProp(grd_List, "NAME", "width", 118);
    }
    //fn_SetGridWidth();

};




/**
 * 그리드 타이틀 세팅_세로
 * AXIS_TYP : 1/기준, 2/가로, 3/세로
 */
scwin.fn_SetGrdTitleVerti = function() {
    // 그리드 초기화
    scwin.fn_InitGrid("3");
    grd_List.ReDraw = false;
    var nIdx = 1;
    var nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "3");
    for (; nRow <= dts_Fz531.getTotalRow(); nRow++) {
        // 세로 세팅
        if (dts_Fz531.getCellData(nRow, "AXIS_TYP") != "3") {
            break;
        }
        dts_List.insertRow();
        dts_List.setCellData(dts_List.getRowPosition(), "NAME", dts_Fz531.getCellData(nRow, "ITEM_NM"));
        nIdx++;
    }
    grd_List.ReDraw = true;
};



/**
 * 조회조건 초기화
 */
scwin.fn_Reset = function() {
    dts_KeyInfo.removeAll();
    dts_Fz531.removeAll();
    dts_Fz530.removeAll();
    $c.stf.setObjectValue(txb_conditionTitle, "");
    scwin.fn_setCondTitle("신규저장");
    rdo_Bas.setValue("");
    rdo_Horiz.setValue("");
    rdo_Verti.setValue("");
    rdo_Bas.setDisabled(false);
    rdo_Bas.Reset();
    rdo_Bas.focus();

    // 전역변수 초기화
    scwin.vAxisType = "";
    scwin.vTmpSave = true;
    scwin.before_bas_btn = 0;
    scwin.before_horiz_btn = 0;
    scwin.before_verti_btn = 0;
    scwin.cond_nm = "";
    scwin.cond_con = "";

    // 그리드 초기화
    scwin.fn_InitGrid("9");
};


/**
 * 그리드 초기화
 * pGubun :1 기준초기화, 2 가로초기화, 3 세로초기화
 */
scwin.fn_InitGrid = function(pGubun) {
    if (pGubun == "9" || pGubun == "1") {
        // 기준초기화
        $c.cm.setColumnProp(grd_List, "NAME", "Name", "");
    }
    if (pGubun == "9" || pGubun == "2") {
        //가로 초기화
        for (var nIdx = 1; nIdx < grd_List.getTotalCol(); nIdx++) {
            $c.cm.setColumnProp(grd_List, "ACCNT_VAL" + nIdx, "Show", false);
        }
    }
    if (pGubun == "9" || pGubun == "3") {
        // 세로 초기화
        dts_List.removeAll();
    }
};



/**
 * dts_Fz531 초기화
 * pGubun :1 기준초기화, 2 가로초기화, 3 세로초기화, 9 모두 초기화
 */
scwin.fn_InitAxisInfo = function(pGubun) {
    if (pGubun == "1" || pGubun == "2" || pGubun == "3") {
        for (var nRow = dts_Fz531.getTotalRow(); nRow >= 1; nRow--) {
            if (pGubun == dts_Fz531.getCellData(nRow, "AXIS_TYP")) {
                $c.cp.removeRow(dts_Fz531, nRow);
            }
        }
    }
    if (pGubun == "9") {
        dts_Fz531.removeAll();
    }
    // 열의 상태를 nomal 로 변경.
    dts_Fz531.ResetStatus();
};


/**
 * dts_Fz531 의 데이터로 연도가 선택가능한지를 리턴한다.
 * return : true 선택가능, false 선택불가
 * 가로항목선택 시 기업, 계정코드 팝업창에서 데이터조회기준년도를 체크 한경우는 연도를 선택 할 수 없다.
 */
scwin.fn_IsSelectYear = function() {
    var bSelect = true;

    // 가로항목 선택한 것이 있는가?
    var nRow = $c.cp.getNameValueRow(dts_Fz531, "AXIS_TYP", "2");
    if (nRow >= 1) {
        // 있다면 COL_YEAR 값을 체크
        var COL_YEAR = dts_Fz531.getCellData(nRow, "COL_YEAR");
        if (COL_YEAR != "0000") {
            bSelect = false;
        }
    }
    return bSelect;
};


/**
 *  조건읽기에서 호출됨. 조건 세팅
 */
scwin.fn_SetCondition = function(pDataset, pCondition) {
    dts_Fz531.removeAll();
    $c.stf.CopyDataSet(pDataset, dts_Fz531, "copyHeader=no");
    dts_KeyInfo.removeAll();
    dts_KeyInfo.insertRow();
    dts_KeyInfo.setCellData(1, "EMP_NO", pDataset.getCellData(1, "EMP_NO"));
    dts_KeyInfo.setCellData(1, "TYP", pDataset.getCellData(1, "COND_TYP"));
    dts_KeyInfo.setCellData(1, "GUBUN", pDataset.getCellData(1, "COND_GUBUN"));
    dts_KeyInfo.setCellData(1, "SEQ_NO", pDataset.getCellData(1, "COND_SEQ"));

    // 조회조건을 화면에 세팅.		
    var aCond = pCondition.split("|");
    var aCondPair;
    for (var i = 0; i < aCond.length; i++) {
        aCondPair = $c.stf.trim(aCond[i]).split("=");
        if (aCondPair[0] == "rdo_Bas") {
            rdo_Bas.setValue(aCondPair[1]);
        } else if (aCondPair[0] == "rdo_Horiz") {
            rdo_Horiz.setValue(aCondPair[1]);
        } else if (aCondPair[0] == "rdo_Verti") {
            rdo_Verti.setValue(aCondPair[1]);
        } else if (aCondPair[0] == "cmb_IND_PTTN") {
            // rdo_Verti.CodeValue = aCondPair[1];

        } else {
            $c.stf.setObjectValue(eval(aCondPair[0]), aCondPair[1]);
        }
    }

    // 기준 축이 없으면 기준지정 비활성.
    var nTmpIdx1 = pDataset.NameValueRow("AXIS_TYP", "1");
    if (nTmpIdx1 < 1) {
        rdo_Bas.setValue("");
        rdo_Bas.setDisabled(true);
        rdo_Bas.Reset();
    } else {
        rdo_Bas.setDisabled(false);
        rdo_Bas.Reset();
    }

    // 그리드 타이틀 세팅.
    scwin.fn_SetGrdTitle("9");

    // 임시저장여부 세팅
    scwin.vTmpSave = false;

    // 이전버튼 세팅
    scwin.fn_setBeforeRadioBtn();

    // 자동조회
    //fn_search();

};





/**
 *  조건저장
 */
scwin.fn_SaveCondition = async function() {
    if (rdo_Bas.getValue() == "" || rdo_Horiz.getValue() == "" || rdo_Verti.getValue() == "") {
        $c.win.alert("항목을 선택하세요");
        return false;
    }

    // 일단 조건을 저장하자. 화면에서 조건을 만들어 넘겼는데 세로항목이 많아지니까 화면에서 뻗어버린다.
    if (!scwin.fn_SaveTemp()) {
        return false;
    }

    //var arrPos = getLeftTopPos(image_1);
    var arrPos = $c.stf.getLeftTopPos(label_9);
    await $c.frame.CreateDialogFrame("YYYY", "./ULDFIS00600_P8.gfm", "조건저장", arrPos[0].LEFT, arrPos[0].TOP, 525 + 20, 205 + 40, "window");
};


/**
 *  조건을 스트링으로 만들기
 * 형태  컨트롤ID=값,컨트롤ID=값 (cmb_CORP_REG_TYP=1,cmb_IND_PTTN=1)
 */
scwin.fn_GetConditionString = function() {
    var tmpStr = "";
    tmpStr += "cmb_IND_PTTN=" + $c.stf.getObjectValue(cmb_IND_PTTN);
    tmpStr += "|cmb_FISCAL_TYP=" + $c.stf.getObjectValue(cmb_FISCAL_TYP);
    tmpStr += "|cmb_INDVDL_CONN_TP=" + $c.stf.getObjectValue(cmb_INDVDL_CONN_TP);
    tmpStr += "|cmb_ACNTG_BAS_TYP=" + $c.stf.getObjectValue(cmb_ACNTG_BAS_TYP);
    tmpStr += "|rdo_Bas=" + $c.stf.getObjectValue(rdo_Bas);
    tmpStr += "|rdo_Horiz=" + $c.stf.getObjectValue(rdo_Horiz);
    tmpStr += "|rdo_Verti=" + $c.stf.getObjectValue(rdo_Verti);
    return tmpStr;
};


/**
 *  조건을 스트링으로 만들기
 * 형태  컨트롤ID=값,컨트롤ID=값 (cmb_CORP_REG_TYP=1,cmb_IND_PTTN=1)
 */
scwin.fn_SetGridWidth = function() {
    // 보이는 컬럼 갯수 구하기.
    var nShowCnt = 0;
    for (var nIdx = 1; nIdx < grd_List.getTotalCol(); nIdx++) {
        //grd_List.ColumnProp("ACCNT_VAL"+nIdx, "Name") = dts_Fz531.NameString(nRow, "ITEM_NM");
        if ($c.cm.getColumnProp(grd_List, grd_List.getColumnID(nIdx), "Show") == "TRUE") {
            nShowCnt++;
        }
    }
    var nWidth = (1245 - 17 - 118) / nShowCnt; // (총크기 - 스크롤크기 - 첫번째컬럼크기)/보이는컬럼갯수
    for (var nIdx = 1; nIdx < grd_List.getTotalCol(); nIdx++) {
        if ($c.cm.getColumnProp(grd_List, grd_List.getColumnID(nIdx), "Show") == "TRUE") {
            $c.cm.setColumnProp(grd_List, grd_List.getColumnID(nIdx, nWidth), "width", '');
        }
    }
};
